insert into public.pokedex_entries (dex, number, species_id, is_default, ko_description, en_description) values
  ('national', 3, 10133, false, '꽃에서 황홀한 향기가 퍼져 나와 싸우는 자의 기분을 달래준다.', 'A bewitching aroma wafts from its flower. The fragrance becalms those engaged in a battle.'),
  ('national', 6, 10134, false, '지상 1400m까지 날개를 사용해 날 수 있다. 고열의 불꽃을 내뿜는다.', 'Its wings can carry this Pokémon close to an altitude of 4,600 feet. It blows out fire at very high temperatures.'),
  ('national', 6, 10135, false, '지상 1400m까지 날개를 사용해 날 수 있다. 고열의 불꽃을 내뿜는다.', 'Its wings can carry this Pokémon close to an altitude of 4,600 feet. It blows out fire at very high temperatures.'),
  ('national', 9, 10136, false, '등껍질의 로켓포에서 뿜어져 나오는 제트 수류는 두꺼운 철판도 뚫는다.', 'The rocket cannons on its shell fire jets of water capable of punching holes through thick steel.'),
  ('national', 15, 10192, false, '양손과 엉덩이에 있는 3개의 독침으로 상대를 찌르고 찌르고 또 찌르며 공격한다.', 'It has three poisonous stingers on its forelegs and its tail. They are used to jab its enemy repeatedly.'),
  ('national', 18, 10175, false, '마하2의 속도로 비행하여 먹이를 찾는다. 그 커다란 발톱은 무기로서도 두려움의 대상이다.', 'This Pokémon flies at Mach 2 speed, seeking prey. Its large talons are feared as wicked weapons.'),
  ('national', 25, 10182, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10183, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10184, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10185, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10186, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 25, 10187, false, '서로의 꼬리를 붙여서 전기를 흐르게 하는 게 피카츄 사이의 인사법이다.', 'Possesses cheek sacs in which it stores electricity. This clever forest-dweller roasts tough berries with an electric shock before consuming them.'),
  ('national', 65, 10137, false, '강력한 초능력을 구사한다. 양손에 든 숟가락은 그 힘으로 만들어낸 것이라고 한다.', 'The longer Alakazam lives, the larger and heavier its head becomes. Our tests have shown that the strength of its psychic powers correlates positively to the weight of its head.'),
  ('national', 80, 10173, false, '셀러에게 물린 충격으로 두 발로 걸을 수 있게 되었다. 셀러가 떨어지면 야돈으로 돌아간다고 한다.', 'Being bitten by a Shellder shocked this Pokémon into standing on two legs. If the Shellder lets go, it seems Slowbro will turn back into a Slowpoke.'),
  ('national', 94, 10138, false, '산에서 조난하면 목숨을 빼앗기 위해 어둠 속에서 나타난다고 한다.', 'Possesses potential victims'' shadows in an effort to steal away the victims'' lives. If your shadow begins to laugh, you must take hold of a protective charm posthaste!'),
  ('national', 115, 10139, false, '새끼가 없는 캥카가 조난한 사람의 아이를 길렀다는 기록이 있다.', 'There are records of a lost human child being raised by a childless Kangaskhan.'),
  ('national', 127, 10140, false, '뿔로 먹이를 찔러 넣어 그대로 두 동강으로 만들거나 강제로 던져버린다.', 'This Pokémon clamps its pincers down on its prey and then either splits the prey in half or flings it away.'),
  ('national', 130, 10141, false, '한번 난동부리기 시작한 갸라도스는 태풍이 사납게 휘몰아쳐도 모든 것을 다 태워버린다.', 'I suspect this Pokémon to be the true identity of a dragon written of in ancient texts, which claimed that it razed an entire village with white-hot beams from its maw.'),
  ('national', 142, 10142, false, '톱 같은 이빨은 강철포켓몬의 피부도 갈기갈기 베어 가른다.', 'Aerodactyl’s sawlike fangs can shred skin to tatters—even the skin of Steel-type Pokémon.'),
  ('national', 150, 10143, false, '뮤의 유전자와 거의 같다. 하지만 크기도 성격도 무서울 정도로 다르다.', 'Its DNA is almost the same as Mew’s. However, its size and disposition are vastly different.'),
  ('national', 150, 10144, false, '뮤의 유전자와 거의 같다. 하지만 크기도 성격도 무서울 정도로 다르다.', 'Its DNA is almost the same as Mew’s. However, its size and disposition are vastly different.'),
  ('national', 181, 10145, false, '꼬리는 강하고 밝게 빛난다. 뱃사람들의 길잡이로서 옛날부터 소중히 여겨져 왔다.', 'Its tail shines bright and strong. It has been prized since long ago as a beacon for sailors.'),
  ('national', 208, 10174, false, '흙과 함께 삼킨 강철이 축적되어 몸이 변화한 것이라 여겨지고 있다.', 'This Pokémon evolved through use of a strange item. Its body is coated with steel powder and notably hard—not even diamond can leave so much as a scratch.'),
  ('national', 212, 10146, false, '몸은 가늘지만 공격력은 무시무시하다. 몸의 근육도 금속으로 되어 있다.', 'Evolved by way of a curious item. The shell covering its body has been shown to be stronger than forged steel.'),
  ('national', 214, 10147, false, '자신 몸무게의 100배에 달하는 무게도 거뜬히 들어 올리는 괴력을 자랑하는 포켓몬이다.', 'This Pokémon has an unparalleled horn. Heracross itself demonstrates tremendous power—it''s capable of throwing several people trained in the traditional arts of war at once.'),
  ('national', 229, 10148, false, '기분 나쁜 울음소리가 특징이다. 옛날 사람들은 지옥에서 온 사자라고 여겨 두려워했다.', 'Identifiable by its eerie howls, people a long time ago thought it was the grim reaper and feared it.'),
  ('national', 248, 10149, false, '지축을 울리면서 걸으면 큰 산조차 무너지며 주변의 지형은 변해버린다.', 'The quakes caused when it walks make even great mountains crumble and change the surrounding terrain.'),
  ('national', 254, 10167, false, '등의 씨앗에는 나무를 건강하게 만드는 영양이 많이 채워져 있다고 전해진다. 숲의 나무를 소중히 키우고 있는 포켓몬이다.', 'Sceptile has seeds growing on its back. They are said to be bursting with nutrients that revitalize trees. This Pokémon raises the trees in a forest with loving care.'),
  ('national', 257, 10150, false, '강인한 하반신을 지녀 30층짜리 빌딩도 가볍게 뛰어넘을 수 있다. 불꽃의 펀치로 상대를 새까맣게 태운다.', 'Blaziken has incredibly strong legs—it can easily clear a 30-story building in one leap. This Pokémon’s blazing punches leave its foes scorched and blackened.'),
  ('national', 260, 10166, false, '대짱이는 파도 소리나 바닷바람의 아주 작은 차이를 지느러미로 감지하여 태풍을 예감한다. 태풍이 불면 바위를 쌓아서 둥지를 지킨다.', 'Swampert predicts storms by sensing subtle differences in the sounds of waves and tidal winds with its fins. If a storm is approaching, it piles up boulders to protect itself.'),
  ('national', 282, 10151, false, '트레이너를 지키기 위해서라면 사이코 파워를 모두 써서 작은 블랙홀을 만들어 낸다.', 'It will dedicate itself to defending a master it has come to adore. Its pure white dress, reminiscent of those worn by ladies of nobility, is the dress of one who is willing to risk their life.'),
  ('national', 302, 10168, false, '보석의 결정을 먹는다. 어둠 속에서는 두 눈이 보석의 빛을 낸다.', 'It feeds on gemstone crystals. In darkness, its eyes sparkle with the glitter of jewels.'),
  ('national', 303, 10152, false, '강철의 뿔이 변형되어 생긴 큰 턱으로 상대를 덥석 문다.', 'It chomps with its gaping mouth. Its huge jaws are actually steel horns that have been transformed.'),
  ('national', 306, 10153, false, '먼 옛날 어떤 왕은 보스로라의 강함을 선망하여 머리 모양을 본떠 만든 투구를 쓰기도 했다.', 'Long ago, there was a king who wore a helmet meant to resemble the head of an Aggron. He was trying to channel the Pokémon’s strength.'),
  ('national', 308, 10154, false, '요가의 힘으로 제6의 감각이 발달하여 사이코 파워를 다룰 수 있게 되었다. 1개월간 아무것도 먹지 않고 명상한다.', 'Through the power of meditation, Medicham developed its sixth sense. It gained the ability to use psychokinetic powers. This Pokémon is known to meditate for a whole month without eating.'),
  ('national', 310, 10155, false, '좀처럼 사람 앞에 모습을 드러내지 않는다. 번개가 떨어진 곳에 보금자리가 있다고 한다.', 'It rarely appears before people. It is said to nest where lightning has fallen.'),
  ('national', 319, 10172, false, '바다의 건달로 불리며 서식하는 해역에 들어간 배는 모조리 공격당한다.', 'This Pokémon is known as the Bully of the Sea. Any ship entering the waters Sharpedo calls home will be attacked—no exceptions.'),
  ('national', 323, 10189, false, '등의 혹은 뼈가 변형된 것이다. 펄펄 끓는 마그마를 가끔 뿜어 올린다. 화났을 때 자주 분화하는 것 같다.', 'The humps on Camerupt’s back are formed by a transformation of its bones. They sometimes blast out molten magma. This Pokémon apparently erupts often when it is enraged.'),
  ('national', 334, 10169, false, '온순한 성질이지만 화나게 하면 날카로운 울음소리로 위협하며 가차 없이 공격한다.', 'This Pokémon has a kind disposition, but if it’s provoked, it will threaten opponents with shrill cries before attacking them without mercy.'),
  ('national', 354, 10156, false, '버려진 원념에 의해 태어난다. 소중히 대하면 만족해서 원래의 인형으로 돌아간다고 한다.', 'Resentment at being cast off made it spring into being. Some say that treating it well will satisfy it, and it will once more become a stuffed toy.'),
  ('national', 359, 10157, false, '위험을 감지하는 능력이 있어 사람들로부터 재앙을 불러오는 포켓몬이라는 오해를 샀다.', 'Because of this Pokémon’s ability to detect danger, people mistook Absol as a bringer of doom.'),
  ('national', 362, 10176, false, '공기 중의 수분을 단숨에 얼게 하는 힘으로 먹이를 냉동시켜 버린다.', 'It covers its body with an armor of ice harder than steel. Uses its breath to freeze prey, which it then devours as if they were frozen desserts.'),
  ('national', 373, 10191, false, '넓은 하늘을 나는 기쁨에 크게 들떠 있지만 화나게 하면 손 쓸 수 없을 정도로 난폭하다.', 'While basking in the joy of flight generally keeps this Pokémon in high spirits, Salamence turns into an uncontrollable menace if something angers it.'),
  ('national', 376, 10178, false, '2마리의 메탕구가 합체한 모습이다. 슈퍼컴퓨터 수준의 두뇌를 사용해 적을 쓰러뜨린다.', 'Metagross is the result of the fusion of two Metang. This Pokémon defeats its opponents through use of its supercomputer-level brain.'),
  ('national', 380, 10164, false, '지능이 높아 사람의 말을 이해한다. 몸을 감싼 유리 같은 깃털로 빛을 굴절시켜 모습을 바꾼다.', 'Latias is highly intelligent and capable of understanding human speech. It is covered with a glass-like down. The Pokémon enfolds its body with its down and refracts light to alter its appearance.'),
  ('national', 381, 10165, false, '상냥한 마음씨를 가진 자만을 따른다. 팔을 접으면 공기저항이 줄어 제트기보다 빠르게 하늘을 난다.', 'Latios will only open its heart to a Trainer with a compassionate spirit. This Pokémon can fly faster than a jet plane by folding its forelegs to minimize air resistance.'),
  ('national', 382, 10179, false, '바다의 화신이라 전해지는 포켓몬. 자연의 힘을 갈구하여 그란돈과 사투를 반복한다는 전설이 있다.', 'Kyogre is said to be the personification of the sea itself. Legends tell of its many clashes against Groudon, as each sought to gain the power of nature.'),
  ('national', 383, 10180, false, '자연의 힘에 의해 원시회귀하여 원래의 모습을 되찾는다. 그 힘은 마그마를 만들어내며 대지를 확장한다.', 'Through Primal Reversion and with nature’s full power, it will take back its true form. It can cause magma to erupt and expand the landmass of the world.'),
  ('national', 384, 10181, false, '오존층을 날아다니며 먹이인 운석을 먹는다. 체내에 모인 운석의 에너지로 메가진화한다.', 'It flies forever through the ozone layer, consuming meteoroids for sustenance. The many meteoroids in its body provide the energy it needs to Mega Evolve.'),
  ('national', 428, 10190, false, '더운 계절이 끝나면 공기를 많이 머금은 털로 털갈이를 하여 추위에 대비한다.', 'Its fur is warm and yet remarkably light. This Pokémon kicks as though it were a master of karate, driving back its opponents with ease.'),
  ('national', 445, 10158, false, '지상에서도 움직임이 빠르다. 설산에서는 체온이 떨어지기 전에 먹이를 잡아 거처로 돌아간다.', 'Soars across the heavens at blinding speed—a magnificent sight! It has a feral disposition. Utmost caution is required if one meets a Garchomp out in the wilds.'),
  ('national', 448, 10159, false, '사람이 생각하는 것도 알 수 있기 때문에 정직한 마음을 가진 트레이너만 따른다.', 'A most gallant-looking creature. It emits energy waves and controls them with precision, using them to sense even faraway beings. I have given the name ”aura” to this power.'),
  ('national', 460, 10160, false, '블리자드를 일으키는 포켓몬이다. 커다란 몸을 흔들면 부근 일대는 금세 새하얗게 된다.', 'A powerful Pokémon that can split huge boulders with ease. Dislikes associating with others and chooses to live quietly deep within the mountains, playing with the snow.'),
  ('national', 475, 10170, false, '도움을 구하는 감정을 민감하게 캐치해서 상대가 있는 곳으로 급히 달려가 가세한다.', 'The blades extending from its elbows are sharper than the finest swords. Its swordsmanship, albeit self-taught, is astonishingly impressive.'),
  ('national', 493, 10085, false, '우주가 아직 생기지 않았을 무렵에 처음으로 태어난 포켓몬이라고 신화 속에서 묘사된다.', 'It is the heavenly fount from which pours the light that shines across Hisui. Its luminance guides and protects all Pokémon. Hisuian mythology states that Arceus is the creator of all things.'),
  ('national', 531, 10171, false, '마음 착한 포켓몬이다. 더듬이를 갖다 대어 상대의 마음과 몸 상태를 파악한다.', 'This Pokémon has a kind heart. By touching with its feelers, Audino can gauge other creatures’ feelings and physical conditions.'),
  ('national', 650, 650, true, '머리와 등이 단단한 껍데기로 덮여 있기 때문에 트럭이 부딪혀와도 아무렇지 않다.', 'Such a thick shell of wood covers its head and back that even a direct hit from a truck wouldn’t faze it.'),
  ('national', 651, 651, true, '동료끼리 몸을 서로 부딪쳐 하반신을 단련한다. 자신이 먼저 싸움을 걸지 않는 온순한 성격이다.', 'They strengthen their lower bodies by running into one another. They are very kind and won’t start fights.'),
  ('national', 652, 652, true, '얼굴 앞에 주먹을 맞대어 방어 포즈를 취하면 폭탄의 직격도 견뎌낸다.', 'When it takes a defensive posture with its fists guarding its face, it could withstand a bomb blast.'),
  ('national', 653, 653, true, '작은 나뭇가지를 들고 다니며 간식 대신 아작아작 먹는다. 귀에서 열기를 뿜어내어 상대를 위협한다.', 'As it walks, it munches on a twig in place of a snack. It intimidates opponents by puffing hot air out of its ears.'),
  ('national', 654, 654, true, '나뭇가지를 꼬리에서 뽑을 때 마찰로 불이 붙는다. 나뭇가지의 불꽃을 흔들어 동료에게 신호를 보낸다.', 'When the twig is plucked from its tail, friction sets the twig alight. The flame is used to send signals to its allies.'),
  ('national', 655, 655, true, '섭씨 3000도의 불꽃 소용돌이를 초능력으로 조종한다. 적을 소용돌이로 감싸 불태운다.', 'Using psychic power, it generates a fiery vortex of 5,400 degrees Fahrenheit, incinerating foes swept into this whirl of flame.'),
  ('national', 656, 656, true, '섬세한 거품으로 몸을 감싸 피부를 보호한다. 태평한 척하면서 빈틈없이 주위를 살핀다.', 'It protects its skin by covering its body in delicate bubbles. Beneath its happy-go-lucky air, it keeps a watchful eye on its surroundings.'),
  ('national', 657, 657, true, '누구보다도 가벼운 몸을 갖고 있다. 600m를 넘는 타워의 꼭대기까지 1분이면 올라간다.', 'Its swiftness is unparalleled. It can scale a tower of more than 2,000 feet in a minute’s time.'),
  ('national', 658, 658, true, '닌자처럼 신출귀몰하다. 재빠른 움직임으로 상대를 농락하면서 물의 수리검으로 벤다.', 'It appears and vanishes with a ninja’s grace. It toys with its enemies using swift movements, while slicing them with throwing stars of sharpest water.'),
  ('national', 659, 659, true, '위험에 민감하다. 아머까오의 날갯소리를 들으면 눈 깜짝할 사이에 구멍을 파고 땅으로 숨어든다.', 'It’s very sensitive to danger. The sound of Corviknight’s flapping will have Bunnelby digging a hole to hide underground in moments.'),
  ('national', 660, 660, true, '배의 털은 보온성이 뛰어나다. 옛날 사람들은 파르토의 몸에서 빠진 털로 방한복을 만들었다.', 'The fur on its belly retains heat exceptionally well. People used to make heavy winter clothing from fur shed by this Pokémon.'),
  ('national', 661, 661, true, '흥분하면 체온이 확 오른다. 맨손으로 만지면 화상을 입기도 할 정도다.', 'When this Pokémon gets excited, its body temperature increases sharply. If you touch a Fletchling with bare hands, you might get burned.'),
  ('national', 662, 662, true, '영역에 대한 개념이 매우 강하고 호전적이다. 먹이 먹는 장소를 두고 불화살빈끼리 싸운다.', 'Fletchinder are exceedingly territorial and aggressive. These Pokémon fight among themselves over feeding grounds.'),
  ('national', 663, 663, true, '시속 500km로 돌격한다. 먹이가 도망칠 틈을 주지 않고 강렬한 발차기로 꼼짝 못 하게 한다.', 'Talonflame dives toward prey at speeds of up to 310 mph and assaults them with powerful kicks, giving the prey no chance to escape.'),
  ('national', 664, 664, true, '몸을 덮은 가루가 체온을 조절하고 있어 어떤 기후나 풍토의 지역에서도 살 수 있다.', 'The powder that covers its body regulates its temperature, so it can live in any region or climate.'),
  ('national', 665, 665, true, '단단한 몸은 새포켓몬의 부리로도 상처 하나 입지 않는다. 가루를 뿌려서 방어한다.', 'The beaks of bird Pokémon can’t begin to scratch its stalwart body. To defend itself, it spews powder.'),
  ('national', 666, 666, true, '살고 있는 장소의 기후나 풍토에 따라 날개의 모양이 다른 포켓몬이다. 화려한 색의 날개 가루를 뿌린다.', 'The patterns on this Pokémon’s wings depend on the climate and topography of its habitat. It scatters colorful scales.'),
  ('national', 666, 10086, false, '살고 있는 장소의 기후나 풍토에 따라 날개의 모양이 다른 포켓몬이다. 화려한 색의 날개 가루를 뿌린다.', 'The patterns on this Pokémon’s wings depend on the climate and topography of its habitat. It scatters colorful scales.'),
